			`config.flags[1].default`},
		{"first duplicate in file order wins", `{"flags":[
			{"key":"f","enabled":true,"default":false,"rules":[]},
			{"key":"g","enabled":true,"enabled":true,"default":false,"default":false,"rules":[]}]}`,
			`config.flags[1].enabled`},
